const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '0.25' },
      { kind: 'text', payload: '0.5' },
      { kind: 'text', payload: '0.75' },
      { kind: 'text', payload: '1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = Math.round(W * 0.10);
    var x1 = Math.round(W * 0.94);
    var y = Math.round(H * 0.55);
    var tickHalf = Math.max(6, Math.round(H * 0.04));
    var paths = [];
    var children = [];

    paths.push({ id: 'axisLine', commands: [['M', x0, y], ['L', x1, y]] });
    children.push({
      type: 'path', pathId: 'axisLine', fill: '#26354a',
      stroke: { width: 2, cap: 'round' }
    });

    var ah = Math.max(10, Math.round(H * 0.05));
    var aw = Math.max(5, Math.round(H * 0.025));
    paths.push({ id: 'arrowHead', commands: [['M', x1 - ah, y - aw], ['L', x1, y], ['L', x1 - ah, y + aw]] });
    children.push({
      type: 'path', pathId: 'arrowHead', fill: '#26354a',
      stroke: { width: 2, cap: 'round', join: 'round' }
    });

    var xs = [];
    var i;
    for (i = 0; i < 5; i++) {
      var xi = x0 + (x1 - x0) * i / 4;
      xs.push(xi);
      var tid = 'tick' + i;
      paths.push({ id: tid, commands: [['M', xi, y - tickHalf], ['L', xi, y + tickHalf]] });
      children.push({
        type: 'path', pathId: tid, fill: '#26354a',
        stroke: { width: 2, cap: 'round' }
      });
    }

    var labelY = y + tickHalf + Math.max(6, Math.round(H * 0.03));
    for (i = 0; i < 5; i++) {
      children.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: xs[i], y: labelY },
        hAlign: 'center',
        vAlign: 'top',
        color: '#26354a'
      });
    }

    return {
      schemaVersion: 1,
      sceneId: 'number-axis-0-to-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
